script:
# 1) Auto tanggal_selesai + kode_tahun_ajaran
if doc.tanggal_mulai:
    mulai = frappe.utils.getdate(doc.tanggal_mulai)
    doc.tanggal_selesai = frappe.utils.getdate(str(mulai.year + 1) + "-06-30")

    yy_mulai = str(mulai.year % 100).zfill(2)
    yy_selesai = str(doc.tanggal_selesai.year % 100).zfill(2)
    doc.kode_tahun_ajaran = yy_mulai + yy_selesai
else:
    doc.tanggal_selesai = None
    doc.kode_tahun_ajaran = None

# 2) Nonaktif -> Arsip (jika field status ada)
has_status = doc.meta.get_field("status") is not None

if int(doc.nonaktif or 0) == 1:
    if has_status:
        doc.status = "Arsip"
else:
    if has_status:
        doc.status = "Aktif"

def extract_years(text):
    s = str(text or "")
    nums = []
    buf = ""

    for ch in s:
        if ch.isdigit():
            buf += ch
        else:
            if len(buf) >= 4:
                nums.append(buf[:4])
            buf = ""
    if len(buf) >= 4:
        nums.append(buf[:4])

    if len(nums) < 2:
        return None

    return nums


if doc.kode_tahun_ajaran and doc.periode_semester:
    ta_row = frappe.db.get_value(
        "Rumba Tahun Ajaran",
        doc.kode_tahun_ajaran,
        ["kode_tahun_ajaran", "nama_tahun_ajaran"],
        as_dict=1
    ) or {}

    kode_ta = ta_row.get("kode_tahun_ajaran") or doc.kode_tahun_ajaran
    ta_text = ta_row.get("nama_tahun_ajaran") or ta_row.get("kode_tahun_ajaran") or doc.kode_tahun_ajaran
    years = extract_years(ta_text)

    if not years:
        frappe.throw("Format Tahun Ajaran harus seperti 2026-2027.")

    y1 = years[0]
    y2 = years[1]

    periode = (doc.periode_semester or "").strip()

    if periode.startswith("S1"):
        doc.kode_semester = str(kode_ta) + "-S1"
        doc.nama_semester = str(kode_ta) + "-SMTR-1"
        doc.tanggal_mulai_semester = str(y1) + "-07-01"
        doc.tanggal_akhir_semester = str(y1) + "-12-31"
    elif periode.startswith("S2"):
        doc.kode_semester = str(kode_ta) + "-S2"
        doc.nama_semester = str(kode_ta) + "-SMTR-2"
        doc.tanggal_mulai_semester = str(y2) + "-01-01"
        doc.tanggal_akhir_semester = str(y2) + "-06-30"
    else:
        frappe.throw("Periode Semester harus diawali S1 atau S2.")
else:
    doc.kode_semester = ""
    doc.nama_semester = ""
    doc.tanggal_mulai_semester = None
    doc.tanggal_akhir_semester = None

if doc.tanggal_mulai_semester and doc.tanggal_akhir_semester:
    if doc.tanggal_mulai_semester > doc.tanggal_akhir_semester:
        frappe.throw("Tanggal Mulai Semester tidak boleh lebih besar dari Tanggal Akhir Semester.")
